-- Version: 20260831070151; name: public_impact_and_traceability

alter table public.cycle_stories add column if not exists public_source_label text; alter table public.cycle_stories add column if not exists public_source_note text; create or replace view public.public_impact_summary with (security_invoker=true) as select (select count(*)::int from public.cycle_stories where status='approved' and consent_confirmed=true and published_at is not null) as published_cycle_stories,(select count(*)::int from public.enterprises where status='approved') as active_partners,(select count(*)::int from public.enterprise_shares where status='approved' and public_result=true) as public_enterprise_shares,(select count(*)::int from public.network_requests where status='completed' and privacy='public_summary') as completed_public_network_requests; grant select on public.public_impact_summary to anon,authenticated; create index if not exists idx_cycle_stories_publication on public.cycle_stories(status,consent_confirmed,published_at desc);
